#include <xrt.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
typedef struct demo {xnetengine* Engine;xnetlistener* Listener;xatomicptr Client,Server;xatomic32 Done,Closed,ListenerClosed;uint64 Cut,Completed;} demo;
static void writeDemoAwait(xatomic32* A,uint32 N){double End=xrtTimer()+5;while(xrtAtomic32Load(A,XMEMORY_ACQUIRE)<N){if(xrtTimer()>End)abort();xrtSleep(1);}}
static void writeDemoProgress(xwsstream* S,ptr Data){demo* D=Data;xwswriteprogress W={.Size=sizeof(W)};if(xrtWsStreamWriteProgress(S,&W)!=XNET_RESULT_OK)abort();if(W.Completed>=D->Cut){D->Completed=W.Completed;xrtAtomic32Store(&D->Done,1,XMEMORY_RELEASE);}}
static void writeDemoClosed(xwsstream* S,const xwsstreamclose* Info,ptr Data){(void)S;(void)Info;xrtAtomic32FetchAdd(&((demo*)Data)->Closed,1,XMEMORY_RELEASE);}
static const xwsstreamevents Events={.Close=writeDemoClosed};
static xwsstream* writeDemoAttach(xnetstream* T,demo* D,xwsrole Role){xwsstreamconfig K;xrtWsStreamConfigInit(&K);K.Role=Role;K.Protocol=XRT_STR_LITERAL("write-progress-demo");xwsstream* S=xrtWsStreamAttach(T,0,&K,&Events,D);if(!S)abort();return S;}
static bool writeDemoAccept(xnetlistener* L,xnetstream* T,ptr Data){(void)L;demo* D=Data;xrtAtomicPtrStore(&D->Server,writeDemoAttach(T,D,XWS_ROLE_SERVER),XMEMORY_RELEASE);return true;}
static void writeDemoOpen(xnetstream* T,ptr Data){demo* D=Data;xwsstream* S=writeDemoAttach(T,D,XWS_ROLE_CLIENT);xrtAtomicPtrStore(&D->Client,S,XMEMORY_RELEASE);if(!xrtWsStreamSetWriteProgress(S,writeDemoProgress)||xrtWsStreamBinary(S,(xbytesview){(cbytes)"HEAD",4})!=XNET_RESULT_OK)abort();xwswriteprogress W={.Size=sizeof(W)};if(xrtWsStreamWriteProgress(S,&W)!=XNET_RESULT_OK)abort();D->Cut=W.Produced;if(W.Completed>=D->Cut){D->Completed=W.Completed;xrtAtomic32Store(&D->Done,1,XMEMORY_RELEASE);}}
static void writeDemoListenerClosed(xnetlistener* L,ptr Data){(void)L;xrtAtomic32Store(&((demo*)Data)->ListenerClosed,1,XMEMORY_RELEASE);}
int main(void){demo D={0};xrtAtomicPtrInit(&D.Client,NULL);xrtAtomicPtrInit(&D.Server,NULL);xrtAtomic32Init(&D.Done,0);xrtAtomic32Init(&D.Closed,0);xrtAtomic32Init(&D.ListenerClosed,0);xnetengineconfig E;xrtNetEngineConfigInit(&E);E.Workers=2;D.Engine=xrtNetEngineCreate(&E);if(!D.Engine||!xrtNetEngineStart(D.Engine))abort();xnetlistenconfig L;xrtNetListenConfigInit(&L);xrtNetAddrLoopback(&L.Address,XNET_FAMILY_IPV4,0);xnetlistenerevents LE={writeDemoAccept,NULL,writeDemoListenerClosed};D.Listener=xrtNetListen(D.Engine,&L,&LE,NULL,&D);xnetaddr A;if(!D.Listener||!xrtNetListenerLocal(D.Listener,&A))abort();xnetstreamevents CE={.Open=writeDemoOpen};if(!xrtNetStreamConnect(D.Engine,&A,1,NULL,&CE,&D))abort();writeDemoAwait(&D.Done,1);printf("saved native prefix=%llu, completed=%llu; local write only\n",(unsigned long long)D.Cut,(unsigned long long)D.Completed);xwsstream* C=xrtAtomicPtrLoad(&D.Client,XMEMORY_ACQUIRE);xwsstream* S;double End=xrtTimer()+5;while(!(S=xrtAtomicPtrLoad(&D.Server,XMEMORY_ACQUIRE))){if(xrtTimer()>End)abort();xrtSleep(1);}xrtWsStreamAbort(C);xrtWsStreamAbort(S);writeDemoAwait(&D.Closed,2);xrtWsStreamDestroy(C);xrtWsStreamDestroy(S);xrtNetListenerClose(D.Listener);writeDemoAwait(&D.ListenerClosed,1);xrtNetListenerDestroy(D.Listener);if(!xrtNetEngineDestroy(D.Engine))abort();return 0;}
